    this.opening = true;
    this.bulkOpened.set(null);
    try {
      const result = await this.claimsApi.openAll([...this.selected()]);
      this.selected.set(new Set());
      this.claims.set(await this.claimsApi.list(sheetId));
      this.bulkOpened.set(result);

